CREATE TABLE payment_order(id BIGINT PRIMARY KEY AUTO_INCREMENT,payment_no VARCHAR(64) NOT NULL UNIQUE,order_no VARCHAR(64) NOT NULL UNIQUE,amount_fen BIGINT NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(32) NOT NULL,channel_transaction_no VARCHAR(64) NULL UNIQUE,paid_at DATETIME(6) NULL,pay_parameters_json JSON NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(order_no) REFERENCES trade_order(order_no),CHECK(amount_fen>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE payment_notification(id BIGINT PRIMARY KEY AUTO_INCREMENT,notification_id VARCHAR(64) NOT NULL UNIQUE,payment_no VARCHAR(64) NOT NULL,payload_hash CHAR(64) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX idx_notification_payment(payment_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mock_payment_transaction(payment_no VARCHAR(64) PRIMARY KEY,order_no VARCHAR(64) NULL,amount_fen BIGINT NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(32) NOT NULL,channel_transaction_no VARCHAR(64) NOT NULL UNIQUE,expires_at DATETIME(6) NULL,paid_at DATETIME(6) NULL,refund_mode VARCHAR(16) NOT NULL DEFAULT 'SUCCESS') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mock_refund_transaction(refund_no VARCHAR(64) PRIMARY KEY,payment_no VARCHAR(64) NOT NULL UNIQUE,amount_fen BIGINT NOT NULL,status VARCHAR(32) NOT NULL,refunded_at DATETIME(6) NULL,FOREIGN KEY(payment_no) REFERENCES mock_payment_transaction(payment_no)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
